			request: {
				required: true,
				mediaType: 'application/x-www-form-urlencoded',
				schema: { $ref: '#/components/schemas/CustomerEditInput' },
			},
			response: {
				kind: 'json',
				schema: { $ref: '#/components/schemas/CustomersEditResponse' },
			},
